    awsCompileApigEvents.apiGatewayMethodLogicalIds = ['method-dependency1', 'method-dependency2'];
    awsCompileApigEvents.provider = provider;
  });

  it('should make base path mappings depend on the generated deployment', () => {
    awsCompileApigEvents.serverless.service.resources = {
      Resources: {
        ApiGatewayBasePathMapping: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          Properties: {},
        },
        ApiGatewayBasePathMappingWithDependency: {
          Type: 'AWS::ApiGateway::BasePathMapping',
          DependsOn: 'ApiGatewayApiKey1',
          Properties: {},
        },
        ApiGatewayApiKey1: {
          Type: 'AWS::ApiGateway::ApiKey',
          Properties: {},
        },
